import math

def max_chocolates(n, a, b, p, q):
    gcd = math.gcd(a, b)
    lcm = a * b // gcd

    dp_red = [0] * (n + 1)
    dp_blue = [0] * (n + 1)

    for i in range(1, n + 1):
        if i % a == 0:
            dp_red[i] = max(dp_red[i], dp_blue[i - 1] + p)
        if i % b == 0:
            dp_blue[i] = max(dp_blue[i], dp_red[i - 1] + q)
        if i % lcm == 0:
            dp_red[i] = max(dp_red[i], dp_blue[i - 1] + p)
            dp_blue[i] = max(dp_blue[i], dp_red[i - 1] + q)

    return max(dp_red[n], dp_blue[n])

